//! Benchmarks of the payment channels pallet.

use super::*;
use frame_benchmarking::v2::*;
use frame_support::traits::{fungible::Mutate, Get};
use frame_system::{pallet_prelude::BlockNumberFor, RawOrigin};
use sp_runtime::traits::{Bounded, Zero};
use tesserax_crypto::Signature;

/// Amount of the benchmark voucher: 1 TESS.
pub const AMOUNT: u128 = 1_000_000_000_000;

/// A voucher of [`AMOUNT`] on channel 0, for the genesis hash `[1; 32]`, generated by the
/// `benchmark_fixture` test.
const VOUCHER: &[u8] = include_bytes!("fixtures/voucher.scale");

fn funded<T: Config>(name: &'static str) -> T::AccountId {
	let who: T::AccountId = account(name, 0, 0);
	T::Currency::set_balance(&who, BalanceOf::<T>::max_value() / 4u32.into());
	who
}

fn voucher() -> (Public, Signature) {
	Decode::decode(&mut &VOUCHER[..]).expect("the fixture is a voucher; qed")
}

/// Channel 0 from a funded payer to a funded payee, signed by the fixture key.
fn channel<T: Config>() -> Result<(T::AccountId, T::AccountId, Signature), BenchmarkError>
where
	BalanceOf<T>: From<u128>,
{
	let genesis = T::Hash::decode(&mut &[1u8; 32][..]).map_err(|_| "32-byte hashes")?;
	frame_system::BlockHash::<T>::insert(BlockNumberFor::<T>::zero(), genesis);
	let (payer, payee) = (funded::<T>("payer"), funded::<T>("payee"));
	let (signer, signature) = voucher();
	NextChannelId::<T>::put(0);
	Pallet::<T>::open(
		RawOrigin::Signed(payer.clone()).into(),
		payee.clone(),
		signer,
		BalanceOf::<T>::from(AMOUNT * 2).max(T::MinDeposit::get()),
	)?;
	Ok((payer, payee, signature))
}

#[benchmarks(where BalanceOf<T>: From<u128>)]
mod benchmarks {
	use super::*;

	#[benchmark]
	fn open() {
		let payer = funded::<T>("payer");
		let payee: T::AccountId = account("payee", 0, 0);
		let (signer, _) = voucher();

		#[extrinsic_call]
		_(RawOrigin::Signed(payer), payee, signer, T::MinDeposit::get());

		assert!(Channels::<T>::contains_key(0));
	}

	#[benchmark]
	fn top_up() -> Result<(), BenchmarkError> {
		let (payer, _, _) = channel::<T>()?;

		#[extrinsic_call]
		_(RawOrigin::Signed(payer), 0, T::MinDeposit::get());

		Ok(())
	}

	/// The first claim of a voucher: signature verification and a transfer to the payee.
	#[benchmark]
	fn claim() -> Result<(), BenchmarkError> {
		let (_, payee, signature) = channel::<T>()?;

		#[extrinsic_call]
		_(RawOrigin::Signed(payee), 0, BalanceOf::<T>::from(AMOUNT), signature);

		assert_eq!(Channels::<T>::get(0).map(|c| c.claimed), Some(BalanceOf::<T>::from(AMOUNT)));
		Ok(())
	}

	#[benchmark]
	fn close() -> Result<(), BenchmarkError> {
		let (_, payee, _) = channel::<T>()?;

		#[extrinsic_call]
		_(RawOrigin::Signed(payee), 0);

		assert!(!Channels::<T>::contains_key(0));
		Ok(())
	}

	#[benchmark]
	fn request_close() -> Result<(), BenchmarkError> {
		let (payer, _, _) = channel::<T>()?;

		#[extrinsic_call]
		_(RawOrigin::Signed(payer), 0);

		Ok(())
	}

	impl_benchmark_test_suite!(Pallet, crate::mock::new_test_ext(), crate::mock::Test);
}
